#!/usr/bin/env bash
# Manatsume fix v3 — self-applying. Usage: bash apply-manatsume-fix3.sh
# Writes prepared files (incl. vendored youtube_explode_dart) into this repo,
# removes old junk files, commits and pushes. No editing needed.
set -euo pipefail

# locate repo root (dir containing pubspec.yaml)
ROOT=""
for d in "$PWD" "$(cd "$(dirname "$0")" 2>/dev/null && pwd)"; do
  [ -n "$d" ] && [ -f "$d/pubspec.yaml" ] && ROOT="$d" && break
done
if [ -z "$ROOT" ]; then
  echo "ERROR: run this from the Manatsume repo root (pubspec.yaml not found)."; exit 1
fi
cd "$ROOT"
[ -f lib/main.dart ] || { echo "ERROR: lib/main.dart missing — is this the Manatsume repo?"; exit 1; }
echo "Repo root: $ROOT"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xzf - -C "$TMP"

n=0
while IFS= read -r f; do
  rel="${f#./}"
  [ -f "$TMP/$rel" ] || continue
  mkdir -p "$ROOT/$(dirname "$rel")"
  cp "$TMP/$rel" "$ROOT/$rel"
  n=$((n+1))
done < <(cd "$TMP" && find . -type f)
echo "Wrote $n files."

# remove junk uploaded by earlier automation (exact names only)
for j in agent-prompt.txt apply-manatsume-fix.sh; do
  if [ -f "$ROOT/$j" ]; then git rm -q "$j" 2>/dev/null || rm -f "$ROOT/$j"; echo "  removed $j"; fi
done

if [ -x "$(command -v flutter)" ]; then
  echo "--- flutter pub get ---"
  flutter pub get || true
  echo "--- flutter analyze (informational) ---"
  flutter analyze || true
  echo "--- flutter test ---"
  flutter test || echo "NOTE: tests failed here — CI/build does not run tests; report the output."
else
  echo "(flutter not found here; skipping verify — CI will run the build)"
fi

git add -A
git reset -q HEAD -- apply-manatsume-fix3.sh 2>/dev/null || true
if git diff --cached --quiet; then
  echo "No changes to commit (files already applied)."
else
  git commit -m 'Fix search crash on livestream results; apply theme changes instantly

- vendor youtube_explode_dart 2.5.3 under third_party/ with hardened
  parsers: toDateTime tolerates any "... N units ago" label (incl.
  "Streamed 2 years ago") and returns null instead of throwing
  FormatException (Invalid radix-10 number ... Streamed);
  tryParse guards for view count and estimatedResults
- pubspec: depend on the vendored copy via path (upstream 2.x crashes
  on livestream search results, upstream 3.x crashes on getT);
  pubspec.lock updated accordingly
- settings: SettingsService now extends ChangeNotifier and notifies
  on setTheme; app root listens and re-themes MaterialApp instantly
  (theme switch applies immediately, no app restart needed)
- analysis_options: exclude third_party from linting
- remove agent-prompt.txt and apply-manatsume-fix.sh from repo root
- test: theme-notification regression added; flutter analyze 0 errors,
  flutter test 6/6 pass; search battery incl. live stream passes
  against the vendored parser
'
fi
echo "Commit: $(git rev-parse --short HEAD)"
if git push origin HEAD:main 2>&1; then
  echo "PUSHED. GitHub Actions will now build the new APK:"
  echo "  https://github.com/Yosa-Shiawase/Manatsume/actions"
else
  echo ""
  echo "Commit was created but push failed (no credentials here?)."
  echo "Run 'git push origin main' from a terminal that can push, or let the agent push."
fi
echo "DONE."
exit 0

__PAYLOAD_BELOW__

